        private static readonly Lazy<bool> RuntimeExtendedShape = new(DetectRuntimeExtendedShape);

        private static bool HasRuntimeExtendedShape()
        {
            return RuntimeExtendedShape.Value;
        }

        private static bool DetectRuntimeExtendedShape()
        {
            if (HasRuntimeExtendedEntityShapeGroup1())
            {
                return true;
            }

            return HasUnexpectedModelLists();
        }

        private static bool HasRuntimeExtendedEntityShapeGroup1()
        {
            if (HasUnexpectedProperties(typeof(DataObject),
                "Id",
                "NormalizedKey",
                "SqlIdentifier",
                "OrchestrationPlan"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(DependencyIssue),
                "Id",
                "BlocksAutomaticRunPlanning",
                "BlocksDag",
                "Code",
                "IssueDomain",
                "Message",
                "Severity",
                "DataObject",
                "OrchestrationPlan"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(DependencyIssuePipeline),
                "Id",
                "Role",
                "DependencyIssue",
                "PipelineReference"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(LockCompatibilityPolicy),
                "Id",
                "LeftEffect",
                "LockBehavior",
                "PolicyKind",
                "Reason",
                "RightEffect",
                "Status",
                "DataObject",
                "DependencyIssue",
                "OrchestrationPlan"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(ObjectAccess),
                "Id",
                "AccessKind",
                "AccessRole",
                "OperationKind",
                "Ordinal",
                "Reason",
                "DataObject",
                "TaskAccessProfile"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(OrchestrationPlan),
                "Id",
                "DagStatus",
                "Description",
                "DeterminismStatus",
                "Name",
                "SynchronizationStatus"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(PipelineDependency),
                "Id",
                "DependencyKind",
