                "Predecessor",
                "Successor"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(PipelineObjectAccess),
                "Id",
                "AccessKind",
                "Reason",
                "DataObject",
                "PipelineReference"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(PipelineReference),
                "Id",
                "MetaPipelinePipelineId",
                "Name",
                "PipelineWorkspacePath",
                "OrchestrationPlan"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(PlannedTask),
                "Id",
                "Ordinal",
                "Reason",
                "PipelineReference",
                "RunPlan",
                "TaskAccessProfile"))
            {
                return true;
            }

            if (HasUnexpectedProperties(typeof(PlannedTaskLock),
